DELIMITER $$
--
-- Procedures
--
CREATE DEFINER=`u154183585_bayhas_aleppo`@`localhost` PROCEDURE `recalculate_inventory` ()   BEGIN

    
    UPDATE warehouse_items wi
    LEFT JOIN (
        SELECT product_id, SUM(quantity) AS total_purchased
        FROM purchase_items
        GROUP BY product_id
    ) pi ON wi.product_id = pi.product_id

    LEFT JOIN (
        SELECT product_id, SUM(quantity_returned) AS total_purchase_returns
        FROM purchase_return_items
        GROUP BY product_id
    ) pri ON wi.product_id = pri.product_id

    LEFT JOIN (
        SELECT item_id AS product_id, SUM(quantity) AS total_sold
        FROM sales_invoice_items
        GROUP BY item_id
    ) si ON wi.product_id = si.product_id

    LEFT JOIN (
        SELECT product_id, SUM(quantity_returned) AS total_sales_returns
        FROM sales_return_items
        GROUP BY product_id
    ) sri ON wi.product_id = sri.product_id

    SET wi.quantity =
        COALESCE(pi.total_purchased, 0)
        - COALESCE(pri.total_purchase_returns, 0)
        - COALESCE(si.total_sold, 0)
        + COALESCE(sri.total_sales_returns, 0);

END$$

DELIMITER ;

